package com.alibaba.otter.canal.common.utils;

import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

import java.net.InetAddress;
import java.net.NetworkInterface;
import java.net.SocketException;

import org.junit.After;
import org.junit.Before;
import org.junit.Test;

import static org.mockito.Mockito.mockStatic;

public class AddressUtilsTest {

    @Test
    public void testGetHostAddressReturnsLocalhostWhenNoInterfaces() throws Exception {
        // Mock NetworkInterface.getNetworkInterfaces() to throw IOException,
        // forcing the fallback path in AddressUtils.getHostAddress()
        try (org.mockito.MockedStatic<NetworkInterface> mockedStatic = mockStatic(NetworkInterface.class)) {
            mockedStatic.when(NetworkInterface::getNetworkInterfaces).thenThrow(new SocketException("no network interfaces"));

            // The correct behavior per the log message is to return 127.0.0.1 (non-null)
            // when no valid interface can be found, NOT null.
            InetAddress result = AddressUtils.getHostAddress();
            assertNotNull("getHostAddress() should return a valid InetAddress (127.0.0.1) when no network interfaces are available, not null", result);
            assertEquals("getHostAddress() should return localhost 127.0.0.1 as fallback", "127.0.0.1", result.getHostAddress());
        }
    }
}

