package com.alibaba.otter.canal.common.zookeeper;

import org.I0Itec.zkclient.exception.ZkException;
import org.apache.zookeeper.ZooKeeper;
import org.junit.Assert;
import org.junit.Test;
import org.mockito.Mockito;

public class ZooKeeperxTest {

    @Test
    public void testConfigMutliClusterRestoresInterruptFlag() throws Exception {
        // Create ZooKeeperx with multiple servers so _serversList.size() > 1
        ZooKeeperx zooKeeperx = new ZooKeeperx("server1:2181;server2:2181");

        // Mock ZooKeeper where close() throws InterruptedException
        ZooKeeper mockZk = Mockito.mock(ZooKeeper.class);
        Mockito.doThrow(new InterruptedException("interrupted")).when(mockZk).close();

        // The reflection in configMutliCluster will fail since it's a mock,
        // triggering the catch block which calls zk.close().
        // zk.close() throws InterruptedException — the bug is that the thread's
        // interrupt status is silently swallowed.
        try {
            zooKeeperx.configMutliCluster(mockZk);
            Assert.fail("Should have thrown ZkException");
        } catch (ZkException e) {
            // Per Java threading convention, the interrupt flag should be restored
            // after catching InterruptedException via Thread.currentThread().interrupt().
            Assert.assertTrue(
                "Interrupt flag should be restored after catching InterruptedException",
                Thread.currentThread().isInterrupted());
        }
    }
}

