package com.alibaba.otter.canal.common.zookeeper;

import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.*;

import org.I0Itec.zkclient.exception.ZkNoNodeException;
import org.apache.zookeeper.CreateMode;
import org.junit.Test;

/**
 * Test that ZkClientx handles single-segment paths (no '/') correctly when
 * ZkNoNodeException is thrown and createParents=true.
 *
 * When create() throws ZkNoNodeException for a path like "nodir" (no slash),
 * the code should NOT crash with StringIndexOutOfBoundsException.
 * Instead it should re-throw ZkNoNodeException since there is no parent
 * directory to create.
 */
public class ZkClientxSingleSegmentPathTest {

    /**
     * Demonstrates the core bug: when path has no '/', lastIndexOf('/') returns -1,
     * and substring(0, -1) throws StringIndexOutOfBoundsException.
     *
     * In the ZkClientx code:
     *   String parentDir = path.substring(0, path.lastIndexOf('/'));
     * With path = "nodir", lastIndexOf('/') = -1, substring(0, -1) → boom.
     */
    @Test
    public void testSubstring_Bug_WithNoSlash() {
        String path = "nodir";
        try {
            String parentDir = path.substring(0, path.lastIndexOf('/'));
            fail("Expected StringIndexOutOfBoundsException but got: " + parentDir);
        } catch (StringIndexOutOfBoundsException e) {
            // This is the BUG: the code crashes instead of handling this gracefully
            // The correct behavior is to detect no parent and re-throw ZkNoNodeException
        }
    }

    /**
     * createPersistentSequential(path, createParents) with a single-segment
     * path (no '/') should re-throw ZkNoNodeException, not crash with
     * StringIndexOutOfBoundsException.
     */
    @Test
    public void testCreatePersistentSequential_NoSlash_Path_Throws_NoNode() {
        ZkClientx client = mock(ZkClientx.class, CALLS_REAL_METHODS);
        doThrow(new ZkNoNodeException("Parent path does not exist")).when(client)
            .create(anyString(), any(), any(CreateMode.class));

        try {
            client.createPersistentSequential("nodir", true);
            fail("Expected ZkNoNodeException");
        } catch (ZkNoNodeException e) {
            // Correct: the real ZkNoNodeException is re-thrown
        } catch (StringIndexOutOfBoundsException e) {
            fail("BUG: StringIndexOutOfBoundsException instead of ZkNoNodeException: " + e.getMessage());
        }
    }

    /**
     * createPersistentSequential(path, data, createParents) with a single-segment
     * path (no '/') should re-throw ZkNoNodeException, not crash with
     * StringIndexOutOfBoundsException.
     */
    @Test
    public void testCreatePersistentSequential_WithData_NoSlash_Path_Throws_NoNode() {
        ZkClientx client = mock(ZkClientx.class, CALLS_REAL_METHODS);
        doThrow(new ZkNoNodeException("Parent path does not exist")).when(client)
            .create(anyString(), any(), any(CreateMode.class));

        try {
            client.createPersistentSequential("nodir", "mydata", true);
            fail("Expected ZkNoNodeException");
        } catch (ZkNoNodeException e) {
            // Correct: the real ZkNoNodeException is re-thrown
        } catch (StringIndexOutOfBoundsException e) {
            fail("BUG: StringIndexOutOfBoundsException instead of ZkNoNodeException: " + e.getMessage());
        }
    }

    /**
     * createPersistent(path, data, createParents) with a single-segment path
     * (no '/') should re-throw ZkNoNodeException, not crash with
     * StringIndexOutOfBoundsException.
     */
    @Test
    public void testCreatePersistent_NoSlash_Path_Throws_NoNode() {
        ZkClientx client = mock(ZkClientx.class, CALLS_REAL_METHODS);
        doThrow(new ZkNoNodeException("Parent path does not exist")).when(client)
            .create(anyString(), any(), any(CreateMode.class));

        try {
            client.createPersistent("nodir", "mydata", true);
            fail("Expected ZkNoNodeException");
        } catch (ZkNoNodeException e) {
            // Correct: the real ZkNoNodeException is re-thrown
        } catch (StringIndexOutOfBoundsException e) {
            fail("BUG: StringIndexOutOfBoundsException instead of ZkNoNodeException: " + e.getMessage());
        }
    }
}

