package com.alibaba.otter.canal.common.zookeeper.running;

import static org.junit.Assert.fail;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.util.concurrent.atomic.AtomicInteger;

import org.I0Itec.zkclient.exception.ZkInterruptedException;
import org.junit.Test;

import com.alibaba.otter.canal.common.zookeeper.ZkClientx;

/**
 * Tests that ServerRunningMonitor.check() does not cause StackOverflowError
 * when ZkInterruptedException is thrown repeatedly.
 */
public class ServerRunningMonitorCheckStackOverflowTest {

    @Test
    public void testCheckShouldNotCauseStackOverflowOnRepeatedZkInterruptedException() {
        ServerRunningMonitor monitor = new ServerRunningMonitor();

        ZkClientx zkClient = mock(ZkClientx.class);
        AtomicInteger callCount = new AtomicInteger(0);

        // Throw ZkInterruptedException many times - enough to blow the stack with recursion.
        // Default JVM stack (1MB) allows ~5000-10000 frames; each check() frame is ~100-200 bytes.
        // 10000 recursive calls will require ~1-2MB of stack, causing StackOverflowError.
        int maxThrows = 10000;
        final ServerRunningData validData = new ServerRunningData();
        validData.setAddress("127.0.0.1:11111");

        when(zkClient.readData(org.mockito.ArgumentMatchers.anyString())).thenAnswer(invocation -> {
            int count = callCount.incrementAndGet();
            if (count < maxThrows) {
                throw new ZkInterruptedException(new InterruptedException("Simulated persistent interruption"));
            }
            // After many retries, succeed with valid data
            return com.alibaba.otter.canal.common.utils.JsonUtils.marshalToByte(validData);
        });

        // Set up the server data so isMine() returns true when we finally succeed
        monitor.setServerData(validData);
        monitor.setDestination("test-dest");
        monitor.setZkClient(zkClient);

        try {
            boolean result = monitor.check();
            // If we get here without StackOverflowError, the method handled the
            // repeated ZkInterruptedException gracefully (e.g., via a loop).
            // That is the CORRECT behavior.
        } catch (StackOverflowError e) {
            fail("check() caused StackOverflowError due to recursive retry on ZkInterruptedException");
        }
    }
}

