package com.alibaba.otter.canal.client.adapter.support;

import java.util.TimeZone;

import org.junit.After;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.*;

/**
 * Test that loading Util does NOT change the JVM's default timezone.
 * The Util class has a static initializer that calls TimeZone.setDefault(),
 * which is a dangerous side effect affecting all code in the same JVM.
 */
public class UtilTimeZoneSideEffectTest {

    private TimeZone originalTimeZone;

    @Before
    public void setUp() {
        // Remember the current default timezone before any test manipulation
        originalTimeZone = TimeZone.getDefault();
    }

    @After
    public void tearDown() {
        // Restore original timezone after each test
        TimeZone.setDefault(originalTimeZone);
    }

    @Test
    public void testLoadingUtilShouldNotChangeJVMDefaultTimeZone() throws Exception {
        // Set a known, non-GMT timezone to make the side effect detectable
        TimeZone testTimeZone = TimeZone.getTimeZone("America/New_York");
        TimeZone.setDefault(testTimeZone);

        // Verify we set it correctly
        assertEquals("America/New_York", TimeZone.getDefault().getID());

        // Force class loading of Util - this triggers the static initializer
        // which currently calls TimeZone.setDefault() - the bug we're testing
        Class<?> utilClass = Class.forName(
            "com.alibaba.otter.canal.client.adapter.support.Util"
        );

        // The correct behavior: loading Util should NOT change JVM default timezone
        // If the bug is present, this assertion will FAIL because Util's static block
        // calls TimeZone.setDefault(TimeZone.getTimeZone("GMT" + timeZone))
        assertEquals(
            "Loading Util must NOT change the JVM's default timezone",
            "America/New_York",
            TimeZone.getDefault().getID()
        );
    }
}

