package com.alibaba.otter.canal.protocol;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

import org.junit.Assert;
import org.junit.Test;

import com.alibaba.otter.canal.protocol.SecurityUtil;

public class SecurityUtilTest {

    @Test
    public void testSimple() throws NoSuchAlgorithmException {
        byte[] seed = { 1, 2, 3, 4, 5, 6, 7, 8 };
        // String str = "e3619321c1a937c46a0d8bd1dac39f93b27d4458"; // canal
        // passwd
        String str = SecurityUtil.scrambleGenPass("canal".getBytes());
        byte[] client = SecurityUtil.scramble411("canal".getBytes(), seed);
        boolean check = SecurityUtil.scrambleServerAuth(client, SecurityUtil.hexStr2Bytes(str), seed);
        Assert.assertTrue(check);
    }

    /**
     * md5String must produce the MD5 of the UTF-8 encoded bytes, regardless of the platform's
     * default charset. When the default charset is ISO-8859-1 (set via surefire argLine), this test
     * verifies that md5String still uses UTF-8.
     *
     * The known-correct UTF-8 MD5 of "测试" is db06c78d1e24cf708a14ce81c9b617ec.
     */
    @Test
    public void testMd5StringUsesUtf8() throws NoSuchAlgorithmException {
        String content = "\u6d4b\u8bd5"; // "测试" – non-ASCII CJK characters
        // Compute the expected MD5 using explicit UTF-8 encoding (the authoritative correct result)
        byte[] utf8Bytes = content.getBytes(StandardCharsets.UTF_8);
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] digest = md.digest(utf8Bytes);
        String expectedMd5 = toHex(digest);

        // md5String should produce the same result as UTF-8 encoding, regardless of default charset
        String actual = SecurityUtil.md5String(content);
        Assert.assertEquals("md5String must use UTF-8 encoding, not platform default charset",
                expectedMd5, actual);
    }

    private String toHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
}

