package com.alibaba.otter.canal.common.zookeeper;

import static org.junit.Assert.assertEquals;

import org.junit.Test;

/**
 * Tests for ZookeeperPathUtils, specifically getBatchMarkNode() precision with large Long values.
 */
public class ZookeeperPathUtilsTest {

    /**
     * Test that getBatchMarkNode preserves the full Long value for batchId > Integer.MAX_VALUE.
     * 
     * The bug: getBatchMarkNode calls batchId.intValue() which truncates the Long to int,
     * losing precision for values > 2,147,483,647.
     * 
     * For batchId = 3,000,000,000L:
     *   Buggy: intValue() wraps to -1,294,967,296, producing "-1294967296"
     *   Correct: should produce "3000000000" (zero-padded to 10 digits)
     */
    @Test
    public void testGetBatchMarkNodeWithLargeBatchId() {
        long largeBatchId = 3_000_000_000L; // > Integer.MAX_VALUE

        String result = ZookeeperPathUtils.getBatchMarkNode(largeBatchId);

        // The correct behavior is to preserve the full Long value, zero-padded
        assertEquals("getBatchMarkNode should preserve full Long value for large batchId",
            "3000000000", result);
    }

    /**
     * Test that getBatchMarkNode works correctly for normal int-range values.
     */
    @Test
    public void testGetBatchMarkNodeWithNormalBatchId() {
        long normalBatchId = 12345L;

        String result = ZookeeperPathUtils.getBatchMarkNode(normalBatchId);

        assertEquals("getBatchMarkNode should zero-pad small batchId to 10 digits",
            "0000012345", result);
    }

    /**
     * Test round-trip: getBatchMarkNode then getBatchMarkId should return the same value.
     * This tests the serialization contract.
     */
    @Test
    public void testBatchIdRoundTripWithLargeValue() {
        long largeBatchId = 3_000_000_000L;

        String node = ZookeeperPathUtils.getBatchMarkNode(largeBatchId);
        long recoveredId = ZookeeperPathUtils.getBatchMarkId(node);

        // Round-trip should preserve the original value
        assertEquals("Round-trip should preserve large batchId",
            largeBatchId, recoveredId);
    }
}

