package com.alibaba.otter.canal.client.impl.running;

import java.lang.reflect.Method;
import java.net.InetSocketAddress;

import org.junit.Assert;
import org.junit.Test;

/**
 * Test that processActiveEnter handles unresolved InetSocketAddress gracefully
 * without throwing NullPointerException when getAddress() returns null.
 */
public class ClientRunningMonitorUnresolvedAddressTest {

    /**
     * When listener.processActiveEnter() returns an InetSocketAddress created
     * with an unresolved hostname, connectAddress.getAddress() returns null.
     * The code at line 217 calls connectAddress.getAddress().getHostAddress()
     * without null-checking, which causes NPE.
     *
     * The correct behavior is to handle this gracefully (e.g., using getHostName()
     * or falling back), not to throw NPE.
     */
    @Test
    public void testProcessActiveEnterWithUnresolvedInetSocketAddress() throws Exception {
        ClientRunningMonitor monitor = new ClientRunningMonitor();

        // Set up the listener that returns an unresolved InetSocketAddress
        // InetSocketAddress.createUnresolved creates an address where getAddress() returns null
        InetSocketAddress unresolvedAddress = InetSocketAddress.createUnresolved("unresolved-hostname.example.com", 11111);

        // Verify that getAddress() is indeed null for this unresolved address
        Assert.assertNull("InetSocketAddress.createUnresolved should have null InetAddress", unresolvedAddress.getAddress());

        monitor.setListener(new ClientRunningListener() {
            @Override
            public InetSocketAddress processActiveEnter() {
                return unresolvedAddress;
            }

            @Override
            public void processActiveExit() {
            }
