package com.alibaba.otter.canal.common.utils;

import static org.junit.Assert.*;

import java.util.regex.Pattern;

import org.junit.Test;

/**
 * Regression test for IP_PATTERN regex bug.
 *
 * The pattern should match exactly 4 octets (a valid IPv4 address) with exactly 3 dots.
 * Pattern with {3,} incorrectly accepts strings like "1.2.3.4.5" which have 4+ dots.
 * Correct quantifier is {3} (exactly 3 repetitions of .[0-9]{1,3} after the first octet).
 * 
 * This test uses the same regex as AddressUtils.IP_PATTERN to verify correctness
 * without requiring the full AddressUtils class to compile (which has external deps).
 */
public class AddressUtilsIpPatternTest {

    // This is the BUGGY pattern from AddressUtils.java line 19
    // private static final Pattern IP_PATTERN = Pattern.compile("[0-9]{1,3}(\\.[0-9]{1,3}){3,}");
    private static final Pattern IP_PATTERN = Pattern.compile("[0-9]{1,3}(\\.[0-9]{1,3}){3,}");

    @Test
    public void testValidIPv4AddressesMatch() {
        assertTrue("192.168.1.1 should match", IP_PATTERN.matcher("192.168.1.1").matches());
        assertTrue("10.0.0.1 should match", IP_PATTERN.matcher("10.0.0.1").matches());
        assertTrue("255.255.255.255 should match", IP_PATTERN.matcher("255.255.255.255").matches());
        assertTrue("0.0.0.0 should match", IP_PATTERN.matcher("0.0.0.0").matches());
        assertTrue("1.2.3.4 should match", IP_PATTERN.matcher("1.2.3.4").matches());
    }

    @Test
    public void testInvalidIPv4TooManyOctetsShouldNotMatch() {
        // "1.2.3.4.5" has 5 octets — not a valid IPv4 address
        assertFalse("1.2.3.4.5 should NOT match (5 octets, too many)",
                IP_PATTERN.matcher("1.2.3.4.5").matches());
        // "1.2.3.4.5.6" has 6 octets — not a valid IPv4 address
        assertFalse("1.2.3.4.5.6 should NOT match (6 octets, too many)",
                IP_PATTERN.matcher("1.2.3.4.5.6").matches());
    }

    @Test
    public void testInvalidIPv4TooFewOctetsShouldNotMatch() {
        assertFalse("1.2.3 should NOT match (only 3 octets)",
                IP_PATTERN.matcher("1.2.3").matches());
        assertFalse("1.2 should NOT match (only 2 octets)",
                IP_PATTERN.matcher("1.2").matches());
    }
}

