package com.alibaba.otter.canal.common.zookeeper;

import static org.mockito.Mockito.*;

import java.lang.reflect.Field;
import java.util.Map;

import org.junit.After;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.Mockito;

/**
 * Tests for ZkClientx resource management.
 */
public class ZkClientxTest {

    @Before
    public void setUp() throws Exception {
        // Clear any cached clients before each test
        ZkClientx.clearClients();
    }

    @After
    public void tearDown() throws Exception {
        ZkClientx.clearClients();
    }

    /**
     * Test that clearClients() properly closes all cached ZkClientx instances
     * before removing them from the cache. This is important to avoid resource
     * leaks where ZooKeeper connections and threads remain open.
     */
    @Test
    public void testClearClientsShouldCloseUnderlyingConnections() throws Exception {
        // Use reflection to access the private static 'clients' map
        Field clientsField = ZkClientx.class.getDeclaredField("clients");
        clientsField.setAccessible(true);
        Map<String, ZkClientx> clients = (Map<String, ZkClientx>) clientsField.get(null);

        // Create a mock ZkClientx so we can verify close() is called
        ZkClientx mockClient = mock(ZkClientx.class);

        // Manually put the mock into the clients map
        clients.put("test-server", mockClient);

        // Verify it's in the cache
        assert clients.size() == 1 : "Expected 1 client in cache";

        // Call the method under test
        ZkClientx.clearClients();

        // Verify the map is cleared
        assert clients.size() == 0 : "Expected 0 clients after clearClients()";

        // THE KEY ASSERTION: verify that close() was called on the mock
        // This is what the correct behavior SHOULD be - clearClients() must
        // close the underlying ZooKeeper connections, not just remove references
        verify(mockClient, atLeastOnce()).close();
    }
}

